import {goTo, type Outcome} from 'play';

export default async function main() {
  let delay = 1000;
  let last: Outcome<unknown>;

  for (let attempt = 0; attempt < 6; attempt++) {
    if (attempt > 0) await new Promise(resolve => setTimeout(resolve, delay));
    last = await goTo('sol_belt');

    if (last.status === 'done') return last;       // arrived
    if (last.status === 'refused') return last;    // must not retry
    if (last.status === 'failed') {
      delay *= 2;                                  // wait 1, 2, 4, 8, 16 s between tries
      continue;                                    // failed (incl. reply lost) is retried
    }
    return last;                                   // partial or otherwise: stop here
  }

  return last;
}
```

Notes on the choices:
- `setTimeout` is a Node global, so it needs no import.
- The loop is bounded (`attempt < 6`), so the static gate that rejects `while(true)` without a `stopped()` check doesn't apply; there are no infinite loops.
- Per the docs, a trip that can't fly is `refused` (a real precondition failure) and is returned at once; a `failed` (broke mid-way, or reply lost) is what we retry, with the backoff doubling each time. A `done` or `partial` ends the run.

