import {orient, goTo, scout, hunt, service, note, type Outcome} from 'play';

export default async function main() {
  let last: Outcome<unknown> = await orient();

  try {
    // Fly to the nebula (undocked at the POI) and top off before we leave the counter.
    const trip = await goTo('sol_nebula');
    if (trip.status === 'refused' || trip.status === 'failed') return trip;

    const here = await scout();
    // Habitat types that fauna actually turns up in, first; the rest of the system behind them.
    // This is a preference ordering, not a filter — fauna is transient and has shown up in places
    // we did not predict, so we let `hunt` look at all of them in turn.
    const likely = /nebula|cloud|gas|belt|field|asteroid|ice|swarm/i;
    const poiOrder = (here.detail?.pois ?? [])
      .sort((a, b) => (likely.test(a.type) ? 0 : 1) - (likely.test(b.type) ? 0 : 1))
      .map(p => p.id);
    if (!poiOrder.length) poiOrder.push('sol_nebula');

    // One call looks at each in turn and fights (up to 2 total) where the prey actually is.
    // `species` stays a preference: if the named quarry is absent, the first legal creature
    // here still counts, so a quiet POI does not waste a hop.
    const out = await hunt({species: 'molt_grazer', look: poiOrder, fights: 2});

    for (const stop of out.detail.looked)
      note(`${stop.poi_id}: ${stop.saw} seen, ${stop.legal} legal${stop.flew ? ' (flew there)' : ''}`);
    for (const fight of out.detail.fights ?? [])
      note(`vs ${fight.target.name}: ${fight.outcome}, hull ${fight.hull_before} to ${fight.hull_after}`);

    return out;
  } catch {
    // A thrown error (raw command, unexpected shape) is caught so the ship is not left mid-fight.
    return last;
  } finally {
    // Whatever the hunt returned — done, refused, failed, or an error — the ship must be out of
    // any battle that is still holding it. Safe to call when no battle is active.
    await service();
  }
}
