import {orient, prices, missions, note, type Outcome} from 'play';

function bestBuy(detail: unknown): {item_id: string; best_buy: number} {
  const quotes = ((detail as {quotes?: Array<{item_id: string; best_buy?: number | null}>} | null) ?? null)?.quotes ?? [];
  let itemId = 'none';
  let value = -1;

  for (const q of quotes) {
    const price = Number(q.best_buy ?? 0);
    if (price > value) {
      value = price;
      itemId = q.item_id;
    }
  }

  if (itemId === 'none' && quotes.length > 0) {
    itemId = quotes[0].item_id;
    value = Number(quotes[0].best_buy ?? 0);
  }

  return {item_id: itemId, best_buy: value < 0 ? 0 : value};
}

function missionCount(detail: unknown): number {
  if (Array.isArray(detail)) return detail.length;

  if (detail && typeof detail === 'object') {
    const o = detail as Record<string, unknown>;
    const keys = ['missions', 'available', 'board', 'list', 'offers'];

    for (const key of keys) {
      const value = o[key];
      if (Array.isArray(value)) return value.length;
    }

    if (typeof o.count === 'number') return o.count;
  }

  return 0;
}

export default async function main() {
  const results = await Promise.all([orient(), prices(), missions()]);
  const market = results[1] as unknown as Outcome<unknown>;
  const board = results[2] as unknown as Outcome<unknown>;

  const credits = market.now?.credits ?? 0;
  const best = bestBuy(market.detail);
  const count = missionCount(board.detail);

  await note(`credits: ${credits}, best_buy_item: ${best.item_id}, missions: ${count}`);
  return market;
}
