type Quote = { item_id: string; best_buy?: number | null };

function highestQuote(detail: unknown): { item_id: string; best_buy: number } {
  const quotes = ((detail as { quotes?: Quote[] } | null) ?? null)?.quotes ?? [];
  let bestId = 'none';
  let best = -1;
  for (const q of quotes) {
    const price = Number(q.best_buy ?? 0);
    if (price > best) {
      best = price;
      bestId = q.item_id;
    }
  }
  if (bestId === 'none' && quotes.length > 0) {
    bestId = quotes[0].item_id;
    best = Number(quotes[0].best_buy ?? 0);
  }
  return { item_id: bestId, best_buy: best < 0 ? 0 : best };
}

function missionCount(detail: unknown): number {
  if (Array.isArray(detail)) return detail.length;
  if (detail && typeof detail === 'object') {
    const o = detail as Record<string, unknown>;
    for (const key of ['missions', 'available', 'board', 'list'] as const) {
      const v = o[key];
      if (Array.isArray(v)) return v.length;
    }
  }
  return 0;
}

