    // hold is not literally empty); an empty gain (reserve only) just skips the sell.
    const took = first.gained?.items ?? [];
    let sold = toStation;
    if (took.length) sold = await sell(took, {from: 'hold'});
    const back = await goTo('sol_debris');
    if (back.status !== 'done') return back;
    return salvage();
  }
  return first;
}
