// A minimal, defensive view of a board mission. The lib's MissionInfo is the real type, but
// we only need its id and a credits reward; reading them loosely keeps this robust to the
// exact field the board exposes for "reward" (reward / credits_reward / reward.credits).
type BoardRow = {id?: string; reward?: unknown; credits_reward?: number; reward_credits?: number};

function rewardOf(m: unknown): number {
  const row = m as BoardRow & Record<string, unknown>;
  // prefer a plain number under the obvious names
  if (typeof row.reward === 'number') return row.reward;
  if (typeof row.credits_reward === 'number') return row.credits_reward;
  if (typeof row.reward_credits === 'number') return row.reward_credits;
  // reward may be an object {credits: n}
  const r = row.reward as Record<string, unknown> | undefined;
  if (r && typeof r.credits === 'number') return r.credits;
  if (r && typeof r.amount === 'number') return r.amount;
  return 0;
}

