    if (rewardOf(m) < 100) continue;          // reward must be at least 100
    if (free - accepted <= 0) break;           // no more free slots

    const res = await acceptMission(row.id);
    if (res.status !== 'done') {
      note(`acceptMission(${row.id}) ${res.status}: ${res.why ?? ''}`);
      break;                                   // stop at the first not-done acceptance
    }
    accepted += 1;
  }

  const done = await completeMissions();
  if (done.status !== 'done') {
    note(`completeMissions ${done.status}: ${done.why ?? ''}`);
  }

  return outcome(
    `accepted ${accepted} mission(s) (reward >= 100, within ${free} free slot(s)) and ran completeMissions`,
    done.status === 'done' ? 'done' : 'partial',
    {accepted}
  );
}

