One type detail to be careful about: I want to annotate the rows I build as `Want[]`, because a `Want` is exactly `{item_id, quantity?}`. I can't `import { type Want }` from `'play'` (that name isn't documented and a bare value import of an unknown name would fail the boundary check), and a `Row[]` annotation would reject the `{item_id}`-only shape. So I define the `Want` type locally — it is structural against the lib's, so `sell(rows)` accepts it.

```ts
import {orient, prices, sell, note} from 'play';

type Want = {item_id: string; quantity?: number};

export default async function main() {
  await orient();

  const book = await prices();
  if (book.status !== 'done') {
    await note('bad book');
    return book;
  }

  const rows: Want[] = (book.detail?.quotes ?? [])
    .filter(q => q.held > 0 && q.best_buy >= 10)
    .map(q => ({item_id: q.item_id}));

  if (rows.length === 0) {
    await note('nothing to sell');
    return book;
  }

  return sell(rows, {from: 'hold'});
}
```

