  }

  const done = await completeMissions();
  if (done.status !== 'done') {
    note(`completeMissions not done: ${done.why ?? done.status}`);
  }

  return outcome(
    `accepted ${accepted} mission(s) and completed them`,
    'done',
    { accepted }
  );
}
