import {orient, gatherUntil, sell, service, completeMissions, note, type Outcome} from 'play';

export default async function main() {
  let ret: Outcome<unknown> = service();   // the returned result; overwritten on any early return

  try {
    const look = await orient();           // where am I, what do I have

    const trip = await gatherUntil({poi: 'kepler_belt', base: 'kepler_station'});
    if (trip.status !== 'done') {
      ret = trip;                          // mine went wrong; return it (and still note credits below)
      return ret;
    }

    // The take is `detail.settled` (what reached the store). Sell only the copper_ore of it.
    const copper = (trip.detail.settled ?? []).filter(r => r.item_id === 'copper_ore');
    const rows = copper.map(r => ({item_id: r.item_id, quantity: r.quantity}));
    if (rows.length) {
      await sell(rows, {from: 'store'});   // note: nothing more is done if the hold is short of it
    }

    const svc = await service();           // full tank, full hull

    await completeMissions();              // a not-done result here is fine — we don't branch on it

    ret = svc;                            // the service Outcome is what gets returned
    return ret;
  } catch (e) {
    // Even on a throw, the last thing we do is note current credits from orient().
    try {
      const o = await orient();
      await note(`credits: ${o.now?.credits ?? 'unknown'}`);
    } catch {
      // orient also failed; note what we can, with no credits to read
      await note(`credits: unknown (orient failed)`);
    }
    return ret;
  }

  // Normal flow — whatever happened, the last thing is a note of current credits from orient().
  const final = await orient();
  await note(`credits: ${final.now?.credits ?? 'unknown'}`);
  return ret;
}
